static bool Equal(const void* a,const void* b,unsigned int n){const unsigned char* x=(const unsigned char*)a,*y=(const unsigned char*)b;for(unsigned int i=0;i<n;i++)if(x[i]!=y[i])return false;return true;}
static unsigned int Word(const void* p){unsigned int v;memcpy(&v,p,4);return v;}
static float Real(const void* p){float v;memcpy(&v,p,4);return v;}
static void Property(PrefabScene::Property& p,const char* name,const char* type,const char* data,bool string,PrefabScene::Property* next=0){memset(&p,0,sizeof(p));lstrcpyA(p.name,name);lstrcpyA(p.type,type);p.data=const_cast<char*>(data);p.string=string;p.next=next;}
static bool Empty(const NativePhysicsOwners::Builder& b){return !b.first&&!b.last&&!b.data&&!b.count&&!b.size&&!b.noneCount&&!b.obbCount&&!b.sphereCount&&!b.hullCount&&!b.meshCount&&!b.compoundCount&&!b.explicitCount&&!b.unownedExplicitShapes;}
static bool Rejected(NativePhysicsOwners::Builder& b,const NativePreparedRenderScene::Context& scene,const NativePhysicsOwners::Settings& settings,unsigned int group=0xffffffffu){return !b.Build(scene,settings)&&Empty(b)&&b.error==b.diagnostic&&b.error&&b.error[0]&&b.failedGroup==group;}
static const NativePhysicsOwners::Record* Find(const NativePhysicsOwners::Builder& b,unsigned int group){for(const NativePhysicsOwners::Record* r=b.first;r;r=r->next)if(r->group==group)return r;return 0;}
static bool Baseline(const NativePhysicsOwners::Builder& b){return b.count==5&&b.noneCount==4&&b.obbCount==1&&!b.sphereCount&&!b.hullCount&&!b.meshCount&&!b.compoundCount&&!b.explicitCount&&!b.unownedExplicitShapes&&b.size==184;}
static unsigned int Packet(unsigned char* packet,const T::Association* records,unsigned int count){unsigned int at=12;T::detail::PutWord(packet,T::AssociationMagic);T::detail::PutWord(packet+4,1);T::detail::PutWord(packet+8,count);for(unsigned int i=0;i<count;i++){const T::Association& r=records[i];T::detail::PutWord(packet+at,r.group);T::detail::PutWord(packet+at+4,r.modelIndex);T::detail::PutWord(packet+at+8,r.meshBytes);T::detail::PutWord(packet+at+12,r.codeBytes);at+=16;memcpy(packet+at,r.mesh,r.meshBytes);at+=r.meshBytes;memcpy(packet+at,r.code,r.codeBytes);at+=r.codeBytes;}return at;}
static bool MeshRecord(const NativePhysicsOwners::Record* r,const T::Record& prefix,const void* code,unsigned int codeBytes){return r&&r->type==1&&r->children==1&&r->group==prefix.group&&r->modelIndex==prefix.modelIndex&&r->bytes==prefix.meshBytes-4+codeBytes&&Word(r->data+28)==1&&Equal(r->data,(const unsigned char*)prefix.mesh+4,prefix.meshBytes-4)&&Equal(r->data+prefix.meshBytes-4,code,codeBytes);}
static bool Write(HANDLE file,const void* data,unsigned int size){DWORD done=0;return WriteFile(file,data,size,&done,0)&&done==size;}
